package fraymus.workspace;
import org.json.*;
import java.util.*;

final class ObservationArtifactReport128 {
    static JSONObject data(JSONObject w){return new JSONObject().put("source",w.getJSONObject("observation128")).put("forecast",w.getJSONObject("forecast128")).put("definition",w.getJSONObject("definition")).put("workflowId",w.getString("id"));}
    static JSONObject build(JSONObject w){var data=data(w);String html="""
        <!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Observed motion explorer</title>
        <style>*{box-sizing:border-box}body{margin:0;background:#101923;color:#e8f0f5;font:16px/1.55 system-ui;padding:clamp(16px,3vw,36px)}main{max-width:1200px;margin:auto}h1{font-size:clamp(25px,4vw,38px);margin:8px 0}.eyebrow{color:#7ee0ce;letter-spacing:.08em;font-size:12px}.muted{color:#a8bac9}label{display:inline-flex;gap:12px;align-items:center;margin:10px 20px 10px 0}select{font:inherit;background:#233547;color:inherit;padding:8px;border-radius:8px}input{max-width:55vw;width:350px}.card{background:#1b2b39;border:1px solid #354958;border-radius:12px;padding:18px;margin:16px 0;overflow-wrap:anywhere}.controls{display:flex;flex-wrap:wrap}svg{width:100%;height:auto;min-height:180px;background:#142330;border-radius:10px}circle[data-series=measured]{fill:#68e2cc}circle[data-series=forecast]{fill:#ffbb70}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:9px;text-align:left;white-space:nowrap;border-bottom:1px solid #354958}.scroll{overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere}.metrics{display:flex;gap:24px;flex-wrap:wrap}.metrics strong{display:block;font-size:24px}button{font:inherit;background:#284457;color:inherit;border:1px solid #64859a;padding:10px;border-radius:7px}</style>
        <main><div class="eyebrow">FRAYNIX / OBSERVATION TO ARTIFACT</div><h1>Motion, measured and predicted</h1><p class="muted">Recorded evidence linked to a persistent world object. Scrub the sequence and compare the two axes.</p><div class="card metrics" id="metrics"></div>
        <div class="controls"><label>Axis <select id="axis"><option value="0">X / metres</option><option value="1">Y / metres</option></select></label><label>Frame <input id="frame" type="range" min="0" step="1"></label></div>
        <p id="selection" class="card"></p><svg id="chart" viewBox="0 0 900 320" role="img" aria-label="Observed and forecast position against source time"></svg><p>Teal: accepted measurement · Amber: causal forecast · Horizontal: source seconds · Vertical: selected axis in metres. Missing points remain missing.</p>
        <p id="future" class="card"></p><p id="uncertainty" class="muted"></p><p id="source" class="card"></p>
        <details open><summary>Every source row and forecast</summary><div class="scroll"><table><thead><tr><th>Frame</th><th>Seconds</th><th>Status</th><th>X m</th><th>Y m</th><th>Radius m</th><th>Forecast X m</th><th>Forecast Y m</th><th>Forecast radius m</th></tr></thead><tbody id="rows"></tbody></table></div></details>
        <details><summary>Source, clock and calibration record</summary><pre id="provenance"></pre></details></main>
        <script id="data128" type="application/json">__JSON__</script><script>
        const d=JSON.parse(document.getElementById('data128').textContent),$=id=>document.getElementById(id),rows=d.forecast.rows,n=v=>v==null?'—':Number(v).toFixed(6);$('frame').max=rows.length-1;$('frame').value=0;
        for(const [label,key] of [['Accepted','measured'],['Forecast comparisons','compared'],['Mean error / m','meanErrorM'],['Missing or rejected','rejected']]){const e=document.createElement('div'),b=document.createElement('strong');b.textContent=key==='meanErrorM'?n(d.forecast.metrics[key]):d.forecast.metrics[key];e.append(b,document.createTextNode(label));$('metrics').append(e)}
        for(const r of rows){const tr=document.createElement('tr');for(const v of [String(r.ordinal),n(r.seconds),r.status,n(r.positionM?.[0]),n(r.positionM?.[1]),n(r.radiusM),n(r.forecast.positionM?.[0]),n(r.forecast.positionM?.[1]),n(r.forecast.radiusM)]){const td=document.createElement('td');td.textContent=v;tr.append(td)}$('rows').append(tr)}
        $('source').textContent='World '+d.source.nativeBinding.worldId+' / body '+d.source.bodyId+' / run '+d.source.runId+'. '+d.source.source+' · '+d.source.license;
        $('uncertainty').textContent=d.forecast.uncertainty+'. '+d.source.uncertaintyMeaning+'. No native world action was applied.';
        $('provenance').textContent=JSON.stringify({geometry:d.source.geometry,clock:d.source.clock,profile:d.source.profile,definition:d.definition},null,2);
        const f=d.forecast.future;$('future').textContent=f.available?'Bounded future at '+n(f.seconds)+' s: X '+n(f.positionM[0])+' m; Y '+n(f.positionM[1])+' m; radius '+n(f.radiusM)+' m. Conditional forecast, not an observation.':'Future withheld: '+f.reason;
        function draw(){const axis=Number($('axis').value),index=Number($('frame').value),r=rows[index];$('selection').textContent='Frame '+r.ordinal+' / '+n(r.seconds)+' s / '+r.status+' / '+(r.forecast.available?'forecast from frames '+r.forecast.fromOrdinals.join(', '):r.forecast.reason);const values=[];for(const q of rows){if(q.accepted&&q.positionM)values.push(q.positionM[axis]);if(q.forecast.available)values.push(q.forecast.positionM[axis])}const lo=Math.min(...values),hi=Math.max(...values),t0=rows[0].seconds,t1=rows.at(-1).seconds;const svg=$('chart');svg.replaceChildren();for(const [series,get] of [['measured',q=>q.accepted?q.positionM:null],['forecast',q=>q.forecast.available?q.forecast.positionM:null]])for(let i=0;i<=index;i++){const q=rows[i],p=get(q);if(!p)continue;const e=document.createElementNS('http://www.w3.org/2000/svg','circle');e.setAttribute('data-series',series);e.setAttribute('data-ordinal',q.ordinal);e.setAttribute('cx',60+780*(q.seconds-t0)/Math.max(1e-9,t1-t0));e.setAttribute('cy',280-240*(p[axis]-lo)/Math.max(1e-9,hi-lo));e.setAttribute('r','4');svg.append(e)}}$('axis').onchange=draw;$('frame').oninput=draw;draw();
        </script></html>
        """.replace("__JSON__",data.toString().replace("<","\\u003c"));
        return new JSONObject().put("title",w.getString("title")).put("files",new JSONObject().put("index.html",html).put("observation.json",data.toString())).put("sources",new JSONArray().put(new JSONObject().put("runId",data.getJSONObject("source").getString("runId")).put("sourceSha256",WorldFrames.hash(data.getJSONObject("source"))).put("codeSha256",ObservationArtifact128.code())));
    }
    static JSONObject audit(JSONObject w,JSONObject artifact,JSONObject actual)throws Exception{
        var rows=w.getJSONObject("forecast128").getJSONArray("rows");var errors=new JSONArray();
        if(!Creation.reference(artifact).similar(w.getJSONObject("report"))||actual.getInt("version")!=artifact.getInt("version")||!actual.getString("id").equals(artifact.getString("id")))throw new IllegalStateException("Artifact reference changed");
        var data=data(w);var source=data.getJSONObject("source");var forecast=w.getJSONObject("forecast128");var m=forecast.getJSONObject("metrics");
        var summary=actual.getJSONArray("summary");var summaryExpected=List.of(""+m.getInt("measured"),""+m.getInt("compared"),String.format(Locale.ROOT,"%.6f",m.getDouble("meanErrorM")),""+m.getInt("rejected"));if(summary.length()!=4)errors.put("Summary count");else for(int i=0;i<4;i++)if(!summary.getString(i).equals(summaryExpected.get(i)))errors.put("Visible summary changed");
        var future=forecast.getJSONObject("future");String expectedFuture=future.getBoolean("available")?String.format(Locale.ROOT,"Bounded future at %.6f s: X %.6f m; Y %.6f m; radius %.6f m. Conditional forecast, not an observation.",future.getDouble("seconds"),future.getJSONArray("positionM").getDouble(0),future.getJSONArray("positionM").getDouble(1),future.getDouble("radiusM")):"Future withheld: "+future.getString("reason");if(!actual.getString("future").equals(expectedFuture))errors.put("Visible future changed");
        String sourceText="World "+source.getJSONObject("nativeBinding").getString("worldId")+" / body "+source.getString("bodyId")+" / run "+source.getString("runId")+". "+source.getString("source")+" · "+source.getString("license");if(!actual.getString("source").equals(sourceText))errors.put("Visible provenance changed");
        var cells=actual.getJSONArray("rows");if(cells.length()!=rows.length())errors.put("Visible row count differs");
        else for(int i=0;i<rows.length();i++){var r=rows.getJSONObject(i);var p=r.getJSONObject("forecast");var expected=new Object[]{r.getInt("ordinal"),r.getDouble("seconds"),r.getString("status"),coordinate(r,0),coordinate(r,1),r.opt("radiusM"),coordinate(p,0),coordinate(p,1),p.opt("radiusM")};var got=cells.getJSONArray(i);if(got.length()!=9){errors.put("Column count");continue;}for(int j=0;j<9;j++){String text=got.getString(j);Object v=expected[j];if(v instanceof Number num){try{if(!Double.isFinite(Double.parseDouble(text))||Math.abs(Double.parseDouble(text)-num.doubleValue())>1.1e-6)errors.put("Source cell "+i+":"+j);}catch(Exception e){errors.put("Nonnumeric source cell");}}else if(!text.equals(v==null?"—":v.toString()))errors.put("Status or missing cell changed");}}
        var frames=actual.getJSONArray("frames");int[] indexes={0,rows.length()-1,rows.length()/2,rows.length()-1};int[] axes={0,0,1,1};
        if(frames.length()!=4)errors.put("Four actual control states required");else for(int k=0;k<4;k++){
            var frame=frames.getJSONObject(k);int axis=axes[k],index=indexes[k];if(frame.getInt("axis")!=axis||frame.getInt("index")!=index||!frame.getBoolean("visible"))errors.put("Control state or chart visibility");
            var selected=rows.getJSONObject(index);if(!frame.getString("selection").contains("Frame "+selected.getInt("ordinal")+" / "+String.format(Locale.ROOT,"%.6f",selected.getDouble("seconds"))+" s / "+selected.getString("status")))errors.put("Selected frame label");
            double lo=Double.POSITIVE_INFINITY,hi=Double.NEGATIVE_INFINITY;for(Object raw:rows){var r=(JSONObject)raw;for(JSONObject p:List.of(r,r.getJSONObject("forecast")))if((p==r?r.getBoolean("accepted"):p.getBoolean("available"))&&p.has("positionM")){double v=p.getJSONArray("positionM").getDouble(axis);lo=Math.min(lo,v);hi=Math.max(hi,v);}}
            var expected=new JSONArray();double first=rows.getJSONObject(0).getDouble("seconds"),last=rows.getJSONObject(rows.length()-1).getDouble("seconds");
            for(String series:List.of("measured","forecast"))for(int i=0;i<=index;i++){var r=rows.getJSONObject(i);var p=series.equals("measured")?r:r.getJSONObject("forecast");if(!(series.equals("measured")?r.getBoolean("accepted"):p.getBoolean("available"))||!p.has("positionM"))continue;expected.put(new JSONObject().put("series",series).put("ordinal",r.getInt("ordinal")).put("x",60+780*(r.getDouble("seconds")-first)/Math.max(1e-9,last-first)).put("y",280-240*(p.getJSONArray("positionM").getDouble(axis)-lo)/Math.max(1e-9,hi-lo)));}
            var points=frame.getJSONArray("points");if(points.length()!=expected.length())errors.put("Plot point count");else for(int i=0;i<points.length();i++){var p=points.getJSONObject(i);var e=expected.getJSONObject(i);if(!p.getBoolean("visible")||!p.getString("series").equals(e.getString("series"))||p.getInt("ordinal")!=e.getInt("ordinal")||!Double.isFinite(p.getDouble("x"))||!Double.isFinite(p.getDouble("y"))||Math.abs(p.getDouble("x")-(double)(float)e.getDouble("x"))>1e-5||Math.abs(p.getDouble("y")-(double)(float)e.getDouble("y"))>1e-5)errors.put("Rendered point changed");}
        }
        return new JSONObject().put("passed",errors.isEmpty()).put("errors",errors).put("artifact",Creation.reference(artifact)).put("dataSha256",WorldFrames.hash(data(w))).put("rows",rows.length()).put("observed",WorldFrames.copy(actual));
    }
    private static Object coordinate(JSONObject p,int axis){return p.has("positionM")?p.getJSONArray("positionM").getDouble(axis):null;}
}
